"use client"

import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent } from "react"
import { motion } from "motion/react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/cn"
import {
  clamp,
  focusRing,
  frameStep,
  pulseMs,
  runFrames,
  SoundHeader,
  toneAllowed,
  toneGain,
  useSoundOn,
  useToneGate,
} from "./tone/feedback-tone"

/**
 * Inspired by beehiiv, Buffer, Quicken, Telegram, and Asana (via Mobbin), original implementation.
 * https://mobbin.com/screens/317c4244-a1e6-4cd1-80f2-db3303cfcd36
 * https://mobbin.com/screens/f01206e2-93f4-48f7-84a2-1d6701dcf953
 * https://mobbin.com/screens/f5107531-79c3-4ef1-b54b-4b7e12b90329
 * https://mobbin.com/screens/6e673605-09a9-4893-b0e3-0046589cc26f
 * https://mobbin.com/screens/426ad7e9-6572-4ad4-afbd-e4f4ee052ae2
 */

export interface LatchGateClickProps {
  pace?: number
  intensity?: number
  style?: LatchStyle
  onPitch?: number
  offPitch?: number
  muted?: boolean
  className?: string
  onValueChange?: (state: { id: string; on: boolean; muted: boolean }) => void
}

export type LatchStyle = "thumb" | "gate"
type LatchId = "mail" | "mentions" | "digest"

interface Slide {
  id: LatchId
  from: number
  to: number
  progress: number
}

const ROWS: readonly { id: LatchId; label: string }[] = [
  { id: "mail", label: "Mail" },
  { id: "mentions", label: "Mentions" },
  { id: "digest", label: "Digest" },
]

export function latchSlide(from: number, to: number, progress: number) {
  const t = clamp(progress, 0, 1)
  return from + (to - from) * t
}

export function LatchGateClick({
  pace = 1,
  intensity = 0.26,
  style = "thumb",
  onPitch = 520,
  offPitch = 340,
  muted = true,
  className,
  onValueChange,
}: LatchGateClickProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const slideRef = useRef<Slide | null>(null)
  const fromPointer = useRef(false)
  const reduced = usePrefersReducedMotion()
  const live = useAnimationActive(rootRef)
  const [soundOn, setSoundOn] = useSoundOn(muted)
  const { audio, frameRef } = useToneGate(live, reduced, soundOn)
  const liveRef = useRef(live)
  const reducedRef = useRef(reduced)
  const soundRef = useRef(soundOn)
  const paceRef = useRef(pace)
  const [on, setOn] = useState<Record<LatchId, boolean>>({ mail: false, mentions: true, digest: false })
  const [slide, setSlide] = useState<Slide | null>(null)
  const [flash, setFlash] = useState<LatchId | "none">("none")
  const [last, setLast] = useState<LatchId>("mail")
  const [plays, setPlays] = useState(0)
  if ((!live || reduced) && (slide || flash !== "none")) {
    if (slide) setSlide(null)
    if (flash !== "none") setFlash("none")
  }

  function toggle(id: LatchId) {
    const nextOn = !on[id]
    setOn((current) => ({ ...current, [id]: nextOn }))
    setLast(id)
    const volume = toneGain(intensity)
    const allowed = toneAllowed({
      muted: !soundRef.current,
      volume,
      reduced: reducedRef.current,
      live: liveRef.current,
    })
    if (allowed) {
      audio.resume()
      const pitch = nextOn ? onPitch : offPitch
      if (audio.playLatch(pitch, pulseMs(70, pace, 40, 100), volume)) setPlays((count) => count + 1)
    }
    if (!liveRef.current || reducedRef.current) {
      slideRef.current = null
      setSlide(null)
      setFlash("none")
      return
    }
    setFlash(id)
    const next = { id, from: nextOn ? 0 : 1, to: nextOn ? 1 : 0, progress: 0 }
    slideRef.current = next
    setSlide(next)
    runFrames(frameRef, () => {
      const current = slideRef.current
      if (!current || !liveRef.current || reducedRef.current) {
        slideRef.current = null
        setSlide(null)
        setFlash("none")
        return false
      }
      const progress = Math.round((current.progress + frameStep(paceRef.current)) * 1000) / 1000
      if (progress >= 1) {
        slideRef.current = null
        setSlide(null)
        setFlash("none")
        return false
      }
      const stepped = { ...current, progress }
      slideRef.current = stepped
      setSlide(stepped)
      return true
    })
  }

  function onPointerDown(id: LatchId, event: PointerEvent<HTMLButtonElement>) {
    if (event.button !== 0) return
    fromPointer.current = true
    toggle(id)
  }

  function onClick(id: LatchId) {
    if (fromPointer.current) {
      fromPointer.current = false
      return
    }
    toggle(id)
  }

  function onKeyDown(id: LatchId, event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key !== "Enter" && event.key !== " ") return
    event.preventDefault()
    fromPointer.current = true
    toggle(id)
  }

  useEffect(() => {
    liveRef.current = live
    reducedRef.current = reduced
    soundRef.current = soundOn
    paceRef.current = pace
  }, [live, reduced, soundOn, pace])

  useEffect(() => {
    onValueChange?.({ id: last, on: on[last], muted: !soundOn })
  }, [last, on, soundOn, onValueChange])

  return (
    <div
      ref={rootRef}
      data-slot="latch-gate-click"
      data-ritual="latch-gate"
      data-motion={reduced ? "off" : "on"}
      data-live={live ? "on" : "off"}
      data-muted={soundOn ? "off" : "on"}
      data-held={!live || reduced || !soundOn ? "on" : "off"}
      data-style={style}
      data-mail={on.mail ? "on" : "off"}
      data-mentions={on.mentions ? "on" : "off"}
      data-digest={on.digest ? "on" : "off"}
      data-flash={flash}
      data-plays={plays}
      className={cn(
        "relative w-full rounded-3xl border border-border bg-card p-4 text-card-foreground motion-reduce:transition-none",
        className,
      )}
    >
      <SoundHeader soundOn={soundOn} onToggle={() => setSoundOn((current) => !current)} />
      <ul className="relative z-10 space-y-2">
        {ROWS.map((row) => {
          const enabled = on[row.id]
          const moving = slide && slide.id === row.id && live && !reduced ? slide : null
          const position = moving ? latchSlide(moving.from, moving.to, moving.progress) : enabled ? 1 : 0
          return (
            <li key={row.id} className="relative">
              <button
                type="button"
                role="switch"
                aria-checked={enabled}
                onPointerDown={(event) => onPointerDown(row.id, event)}
                onClick={() => onClick(row.id)}
                onKeyDown={(event) => onKeyDown(row.id, event)}
                className={cn(
                  "flex w-full items-center justify-between rounded-2xl border border-border bg-background px-3 py-3 text-sm text-foreground",
                  focusRing,
                )}
              >
                <span>{row.label}</span>
                {style === "gate" ? (
                  <span className="relative h-6 w-5 overflow-hidden rounded-sm border border-border bg-muted" aria-hidden="true">
                    <span
                      data-gate=""
                      className="absolute inset-x-0 bottom-0 bg-primary"
                      style={{ height: `${Math.round(position * 100)}%` }}
                    />
                  </span>
                ) : (
                  <span
                    className={cn("relative h-6 w-11 rounded-full", enabled ? "bg-primary" : "bg-muted")}
                    aria-hidden="true"
                  >
                    <span
                      data-thumb=""
                      className="absolute top-0.5 h-5 w-5 rounded-full bg-background"
                      style={{ left: `${2 + position * 18}px` }}
                    />
                  </span>
                )}
              </button>
              {flash === row.id && live && !reduced ? (
                <motion.span
                  data-latch-flash=""
                  aria-hidden="true"
                  style={{ pointerEvents: "none", opacity: 0.25 + clamp(intensity, 0, 1) * 0.35 }}
                  className="pointer-events-none absolute inset-y-2 right-3 w-1 rounded-full bg-primary motion-reduce:transition-none"
                />
              ) : null}
            </li>
          )
        })}
      </ul>
    </div>
  )
}

"use client"

import { useEffect, useRef, useState, type ReactNode } from "react"
import { cn } from "@/lib/cn"

/**
 * 原创短音合成。只在用户手势里 resume，离开视口或减弱动效时停掉。
 * 不采集输入设备，也不画实时频谱。
 */

export const mutedNotice = "Demo starts muted — unmute to hear short UI tones."

export const focusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"

export function clamp(value: number, min: number, max: number) {
  if (!Number.isFinite(value)) return min
  return Math.min(max, Math.max(min, value))
}

export function paceRate(pace: number) {
  return Number.isFinite(pace) && pace > 0 ? pace : 1
}

export function pulseMs(base: number, pace: number, min: number, max: number) {
  return Math.round(clamp(base / paceRate(pace), min, max))
}

export function toneGain(intensity: number, ceiling = 0.12) {
  return Math.round(clamp(intensity, 0, 1) * ceiling * 1000) / 1000
}

export function frameStep(pace: number) {
  return Math.round(clamp(0.18 * paceRate(pace), 0.08, 0.45) * 1000) / 1000
}

export interface ToneGate {
  muted: boolean
  volume: number
  reduced: boolean
  live: boolean
}

export function toneAllowed(gate: ToneGate) {
  return gate.live && !gate.reduced && !gate.muted && gate.volume > 0
}

export interface StagePoint {
  x: number
  y: number
}

export function stagePoint(
  root: HTMLElement | null,
  node: HTMLElement,
  event: { clientX: number; clientY: number } | null,
  fallback: StagePoint,
): StagePoint {
  const rootRect = root?.getBoundingClientRect()
  const rect = node.getBoundingClientRect()
  const originX = rootRect?.left ?? 0
  const originY = rootRect?.top ?? 0
  if (!event) {
    const width = rect.width > 0 ? rect.width : fallback.x
    const height = rect.height > 0 ? rect.height : fallback.y
    return { x: rect.left - originX + width / 2, y: rect.top - originY + height / 2 }
  }
  return { x: event.clientX - originX, y: event.clientY - originY }
}

export function cancelFrame(frameRef: { current: number }) {
  if (frameRef.current === 0) return
  window.cancelAnimationFrame(frameRef.current)
  frameRef.current = 0
}

export function runFrames(frameRef: { current: number }, keepGoing: () => boolean) {
  if (frameRef.current !== 0) return
  const tick = () => {
    if (!keepGoing()) {
      frameRef.current = 0
      return
    }
    frameRef.current = window.requestAnimationFrame(tick)
  }
  frameRef.current = window.requestAnimationFrame(tick)
}

export function useSoundOn(muted: boolean) {
  const [soundOn, setSoundOn] = useState(!muted)
  const [seen, setSeen] = useState(muted)
  if (seen !== muted) {
    setSeen(muted)
    setSoundOn(!muted)
  }
  return [soundOn, setSoundOn] as const
}

export function useLevel(volume: number) {
  const [level, setLevel] = useState(volume)
  const [seen, setSeen] = useState(volume)
  if (seen !== volume) {
    setSeen(volume)
    setLevel(volume)
  }
  return [level, setLevel] as const
}

interface Stoppable {
  stop: () => void
}

export interface FeedbackAudio {
  resume: () => void
  stopAll: () => void
  close: () => void
  playTick: (pitch: number, ms: number, volume: number) => boolean
  playChime: (kind: "soft" | "bright", ms: number, volume: number) => boolean
  playBuzz: (band: "low" | "mid", ms: number, volume: number) => boolean
  playLatch: (pitch: number, ms: number, volume: number) => boolean
  playWhoosh: (ms: number, volume: number) => boolean
  playCone: (ms: number, volume: number) => boolean
}

export function createFeedbackAudio(): FeedbackAudio {
  let audio: AudioContext | null = null
  const active = new Set<Stoppable>()

  function context() {
    if (audio && audio.state !== "closed") return audio
    if (typeof window === "undefined") return null
    const Ctor = window.AudioContext ?? window.webkitAudioContext
    if (!Ctor) return null
    try {
      audio = new Ctor()
    } catch {
      audio = null
    }
    return audio
  }

  function resume() {
    const current = context()
    if (current && current.state === "suspended") void current.resume()
  }

  function stopAll() {
    for (const entry of [...active]) entry.stop()
    active.clear()
  }

  function close() {
    stopAll()
    const current = audio
    audio = null
    if (current && current.state !== "closed") void current.close()
  }

  function envelope(gain: GainNode, current: AudioContext, volume: number, seconds: number, delay: number) {
    const now = current.currentTime + delay
    const peak = Math.max(0.0001, volume)
    const attack = Math.min(0.015, seconds * 0.3)
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(peak, now + attack)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + Math.max(seconds, attack + 0.01))
  }

  function arm(
    node: OscillatorNode | AudioBufferSourceNode,
    gain: GainNode,
    current: AudioContext,
    seconds: number,
    delay: number,
  ) {
    let stopped = false
    const entry: Stoppable = {
      stop: () => {
        if (stopped) return
        stopped = true
        active.delete(entry)
        const at = current.currentTime
        try {
          gain.gain.cancelScheduledValues(at)
          gain.gain.setValueAtTime(0.0001, at)
        } catch {
          /* context already closed */
        }
        try {
          node.stop()
        } catch {
          /* node already stopped */
        }
        try {
          node.disconnect()
          gain.disconnect()
        } catch {
          /* node already disconnected */
        }
      },
    }
    active.add(entry)
    node.onended = () => entry.stop()
    const startAt = current.currentTime + delay
    node.start(startAt)
    try {
      node.stop(startAt + seconds)
    } catch {
      entry.stop()
    }
  }

  function tone(frequency: number, type: OscillatorType, ms: number, volume: number, delay = 0) {
    if (!(volume > 0) || !(ms > 0)) return false
    const current = context()
    if (!current) return false
    const seconds = ms / 1000
    const osc = current.createOscillator()
    const gain = current.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(Math.max(40, frequency), current.currentTime + delay)
    envelope(gain, current, volume, seconds, delay)
    osc.connect(gain)
    gain.connect(current.destination)
    arm(osc, gain, current, seconds, delay)
    return true
  }

  function attempt(run: () => boolean) {
    try {
      return run()
    } catch {
      return false
    }
  }

  return {
    resume,
    stopAll,
    close,
    playTick: (pitch, ms, volume) => attempt(() => tone(pitch, "square", ms, volume)),
    playChime: (kind, ms, volume) =>
      attempt(() => {
        const low = kind === "bright" ? 784 : 523
        const high = kind === "bright" ? 1046 : 659
        const note = ms * 0.62
        const first = tone(low, "sine", note, volume)
        const second = tone(high, "sine", note, volume * 0.85, (ms / 1000) * 0.32)
        return first || second
      }),
    playBuzz: (band, ms, volume) => attempt(() => tone(band === "mid" ? 160 : 90, "sawtooth", ms, volume)),
    playLatch: (pitch, ms, volume) => attempt(() => tone(pitch, "triangle", ms, volume)),
    playWhoosh: (ms, volume) =>
      attempt(() => {
        if (!(volume > 0) || !(ms > 0)) return false
        const current = context()
        if (!current) return false
        const seconds = ms / 1000
        const length = Math.max(1, Math.floor(current.sampleRate * seconds))
        const buffer = current.createBuffer(1, length, current.sampleRate)
        const data = buffer.getChannelData(0)
        for (let index = 0; index < data.length; index += 1) {
          const env = 1 - index / data.length
          data[index] = (Math.random() * 2 - 1) * env * env
        }
        const source = current.createBufferSource()
        const filter = current.createBiquadFilter()
        const gain = current.createGain()
        source.buffer = buffer
        filter.type = "bandpass"
        filter.frequency.setValueAtTime(880, current.currentTime)
        filter.Q.value = 0.7
        envelope(gain, current, volume, seconds, 0)
        source.connect(filter)
        filter.connect(gain)
        gain.connect(current.destination)
        arm(source, gain, current, seconds, 0)
        return true
      }),
    playCone: (ms, volume) => attempt(() => tone(520, "sine", ms, volume)),
  }
}

export function useToneGate(live: boolean, reduced: boolean, soundOn: boolean) {
  const [audio] = useState(createFeedbackAudio)
  const frameRef = useRef(0)

  useEffect(() => {
    if (live && !reduced && soundOn) return
    cancelFrame(frameRef)
    audio.stopAll()
  }, [audio, live, reduced, soundOn])

  useEffect(
    () => () => {
      cancelFrame(frameRef)
      audio.close()
    },
    [audio],
  )

  return { audio, frameRef }
}

export function SoundHeader({
  soundOn,
  onToggle,
  hideToggle = false,
  extra,
}: {
  soundOn: boolean
  onToggle?: () => void
  hideToggle?: boolean
  extra?: ReactNode
}) {
  return (
    <div className="relative z-10 mb-3 flex flex-wrap items-center justify-between gap-2">
      <p className="max-w-sm text-xs text-muted-foreground">{mutedNotice}</p>
      <div className="flex flex-wrap items-center gap-2">
        {extra}
        {hideToggle ? null : (
          <button
            type="button"
            aria-pressed={soundOn}
            onClick={onToggle}
            className={cn(
              "rounded-full border border-border bg-background px-3 py-1 text-xs font-medium text-foreground",
              focusRing,
            )}
          >
            {soundOn ? "Mute" : "Unmute"}
          </button>
        )}
        <span data-sound-label="" className="text-xs text-muted-foreground">
          {soundOn ? "Sound on" : "Sound off"}
        </span>
      </div>
    </div>
  )
}

declare global {
  interface Window {
    webkitAudioContext?: typeof AudioContext
  }
}
